$ErrorActionPreference = "Stop"

$projectRoot =
    Split-Path -Parent $PSScriptRoot

$helperPath =
    Join-Path `
        $projectRoot `
        "lib\brain-multi-slot.ts"

$respondPath =
    Join-Path `
        $projectRoot `
        "app\api\brain\respond\route.ts"

if (-not (
    Test-Path -LiteralPath $respondPath
)) {
    throw "Brain respond route introuvable."
}

$helper64 = ""
$payloadType64 = "dHlwZSBCcmFpblBheWxvYWQgPSBCcmFpbkNvbnRleHQgJiB7CiAgbWlzc2luZzogc3RyaW5nW107CiAgcmVhZHk6IGJvb2xlYW47CiAgcmVhZGluZXNzOiBCcmFpblJlYWRpbmVzc1BheWxvYWQ7CiAgc2NoZWR1bGU6IEJyYWluTXVsdGlTbG90U2NoZWR1bGUgfCBudWxsOwp9Ow=="
$handlerBlock64 = ""

function DecodeText {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Value
    )

    return [System.Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String(
            $Value
        )
    )
}

$helper =
    DecodeText $helper64

$payloadType =
    DecodeText $payloadType64

$handlerBlock =
    DecodeText $handlerBlock64

$timestamp =
    Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @(
    $helperPath,
    $respondPath
)) {
    if (
        Test-Path -LiteralPath $path
    ) {
        Copy-Item `
            -LiteralPath $path `
            -Destination (
                $path +
                ".bak-12-82-" +
                $timestamp
            ) `
            -Force
    }
}

$utf8NoBom =
    New-Object System.Text.UTF8Encoding($false)

[System.IO.File]::WriteAllText(
    $helperPath,
    $helper,
    $utf8NoBom
)

$route =
    [System.IO.File]::ReadAllText(
        $respondPath
    )

if (
    -not $route.Contains(
        "KLYX_MULTI_SLOT_INTEGRATION_12_82"
    )
) {
    # ==========================================
    # IMPORT
    # ==========================================

    $importAnchor =
        '} from "@/lib/api-auth";'

    $newImport =
        'import {' +
        "`n" +
        '  buildMultiSlotReply,' +
        "`n" +
        '  parseMultiSlotSchedule,' +
        "`n" +
        '  type BrainMultiSlotSchedule,' +
        "`n" +
        '} from "@/lib/brain-multi-slot";'

    if (
        -not $route.Contains(
            $importAnchor
        )
    ) {
        throw "Ancre import api-auth introuvable."
    }

    $route =
        $route.Replace(
            $importAnchor,
            $importAnchor +
            "`n" +
            $newImport
        )

    # ==========================================
    # PAYLOAD TYPE
    # ==========================================

    $payloadStart =
        $route.IndexOf(
            "type BrainPayload = BrainContext & {"
        )

    if (
        $payloadStart -lt 0
    ) {
        throw "Type BrainPayload introuvable."
    }

    $payloadEnd =
        $route.IndexOf(
            "};",
            $payloadStart
        )

    if (
        $payloadEnd -lt 0
    ) {
        throw "Fin BrainPayload introuvable."
    }

    $payloadEnd += 2

    $route =
        $route.Substring(
            0,
            $payloadStart
        ) +
        $payloadType +
        $route.Substring(
            $payloadEnd
        )

    # ==========================================
    # POST HANDLER
    # ==========================================

    $handlerStart =
        $route.IndexOf(
            "    const context = await applyUserMemory("
        )

    if (
        $handlerStart -lt 0
    ) {
        throw "Ancre applyUserMemory introuvable."
    }

    $handlerEnd =
        $route.IndexOf(
            "    await insertBrainMessage({",
            $handlerStart
        )

    if (
        $handlerEnd -lt 0
    ) {
        throw "Ancre insertBrainMessage introuvable."
    }

    $route =
        $route.Substring(
            0,
            $handlerStart
        ) +
        $handlerBlock +
        $route.Substring(
            $handlerEnd
        )
}

$checks = @(
    @{
        Name = "helper marker"
        Value =
            $helper.Contains(
                "KLYX_MULTI_SLOT_BRAIN_12_82"
            )
    },
    @{
        Name = "route integration"
        Value =
            $route.Contains(
                "KLYX_MULTI_SLOT_INTEGRATION_12_82"
            )
    },
    @{
        Name = "schedule payload"
        Value =
            $route.Contains(
                "schedule: BrainMultiSlotSchedule | null"
            )
    },
    @{
        Name = "parser call"
        Value =
            $route.Contains(
                "parseMultiSlotSchedule("
            )
    },
    @{
        Name = "protected publication"
        Value =
            $route.Contains(
                '"publication_multi_creneaux"'
            )
    }
)

foreach ($check in $checks) {
    if (-not $check.Value) {
        throw "12.82 validation failed : $($check.Name)"
    }
}

[System.IO.File]::WriteAllText(
    $respondPath,
    $route,
    $utf8NoBom
)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.82 APPLIQUE"
Write-Host "======================================"
Write-Host "Multi-creneaux : OK"
Write-Host "Multi-budgets : OK"
Write-Host "Calcul durees : OK"
Write-Host "Calcul budget/h : OK"
Write-Host "Calcul totaux : OK"
Write-Host "Publication mono-creneau accidentelle : BLOQUEE"
Write-Host ""